mapper.select:
SET NOCOUNT ON;
DECLARE @targetLocation GEOGRAPHY;
DECLARE @targetBrandId BIGINT;

SELECT @targetLocation = location, @targetBrandId = brand_id 
FROM branches_51 
WHERE branch_id = #{branchId};

SELECT COUNT(*)
FROM branches_51 b
WHERE b.brand_id = @targetBrandId
  AND b.branch_id <> #{branchId}
  AND b.location.STDistance(@targetLocation) <= #{radius}
  AND b.is_deleted = 'n'
  AND b.operating_status = 'OPERATING'
